#import <XCTest/XCTest.h>
#import "PepperJumpNoiseXORCipher.hpp"
#import "PrintExamplesHelper.hpp"
#import "CipherGauntlet.hpp"
#include <memory>

@interface Battery_PepperJumpNoiseXORCipher : XCTestCase

@end

@implementation Battery_PepperJumpNoiseXORCipher

- (void)test_gauntlet_PepperJumpNoiseXORCipher {
    static std::uint8_t aAllZero[SOCCER_BLOCK_SIZE];
    static std::uint8_t aAllOne[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandA[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandB[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandC[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandD[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandE[SOCCER_BLOCK_SIZE];
    static std::uint8_t aRandF[SOCCER_BLOCK_SIZE];
    
    CipherGauntlet::ArrayZero(aAllZero, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayOne(aAllOne, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandA, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandB, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandC, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandD, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandE, SOCCER_BLOCK_SIZE);
    CipherGauntlet::ArrayRandomize(aRandF, SOCCER_BLOCK_SIZE);
    
    std::vector<std::uint8_t *> aListMask;
    std::vector<std::uint8_t *> aListNoise;
    std::vector<std::uint8_t *> aListMaskJumps;
    std::vector<std::uint8_t *> aListNoiseJumps;
    
    aListMask.push_back(aRandA); aListMask.push_back(aRandB); aListMask.push_back(aRandC); aListMask.push_back(aRandD);
    aListMask.push_back(aRandE); aListMask.push_back(aRandF);
    aListMask.push_back(aAllZero); aListMask.push_back(aAllOne);
    
    aListNoise.push_back(aRandA); aListNoise.push_back(aRandB); aListNoise.push_back(aRandC); aListNoise.push_back(aRandD);
    aListNoise.push_back(aRandE); aListNoise.push_back(aRandF);
    aListNoise.push_back(aAllZero); aListNoise.push_back(aAllOne);
    
    aListMaskJumps.push_back(aRandA); aListMaskJumps.push_back(aRandB); aListMaskJumps.push_back(aRandC); aListMaskJumps.push_back(aRandD);
    aListMaskJumps.push_back(aRandE); aListMaskJumps.push_back(aRandF);
    aListMaskJumps.push_back(aAllZero); aListMaskJumps.push_back(aAllOne);
    
    static CipherGauntlet aGauntlet;
    
    for (std::size_t aIndexA=0; aIndexA<aListMask.size(); aIndexA++) {
        std::uint8_t *aMask = aListMask[aIndexA];
        for (std::size_t aIndexB=0; aIndexB<aListNoise.size(); aIndexB++) {
            std::uint8_t *aNoise = aListNoise[aIndexB];
            for (std::size_t aIndexC=0; aIndexC<aListMaskJumps.size(); aIndexC++) {
                std::uint8_t *aMaskJumps = aListMaskJumps[aIndexC];
                
                PepperJumpNoiseXORCipher aCipher(aMask,
                                                 aNoise,
                                                 aMaskJumps);
                if (!aGauntlet.RunCipher(&aCipher,
                                         16,
                                         "PepperJumpNoiseXORCipher")) {
                    XCTFail("[PepperJumpNoiseXORCipher] test_gauntlet_PepperJumpNoiseXORCipher failed.");
                    return;
                }
            }
            
        }
    }
}

- (void)test_fixed_16_A_PepperJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 00000000  00000000
    // bit1 00000000  00000000
    // bit2 00000000  00000000
    // bit3 00000000  00000000
    // bit4 00000000  00000000
    // bit5 00000000  00000000
    // bit6 00000000  00000000
    // bit7 00000000  00000000
    //
    // After Cipher:
    // bit0 11010000  10111111
    // bit1 11101111  10000110
    // bit2 11100110  01010100
    // bit3 01000101  11110001
    // bit4 00000000  01011000
    // bit5 01110011  11001011
    // bit6 10000110  10000110
    // bit7 01101010  00001011
    //
    // Avalanche:
    // bit0 XX.X....  X.XXXXXX
    // bit1 XXX.XXXX  X....XX.
    // bit2 XXX..XX.  .X.X.X..
    // bit3 .X...X.X  XXXX...X
    // bit4 ........  .X.XX...
    // bit5 .XXX..XX  XX..X.XX
    // bit6 X....XX.  X....XX.
    // bit7 .XX.X.X.  ....X.XX
    // Avalanche: 48.44%

    const std::uint8_t aOriginal[16] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };

    const std::uint8_t aMaskBuffer[16] = {
        0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00
    };

    const std::uint8_t aNoiseBuffer[16] = {
        0xE2, 0xF5, 0x65, 0x84, 0x41, 0x72, 0x67, 0x54, 0xD6, 0x3C, 0x90, 0xB8, 0x8D, 0xE2, 0xC7, 0x95
    };

    const std::uint8_t aMaskJumpBuffer[16] = {
        0x94, 0xA2, 0xA4, 0x5B, 0x9B, 0xE4, 0x78, 0x06, 0x07, 0xEF, 0xE8, 0x3A, 0x03, 0x0A, 0x15, 0x1C
    };

    PepperJumpNoiseXORCipher aCrypt(aMaskBuffer,
        aNoiseBuffer,
        aMaskJumpBuffer);

    const std::uint8_t aExpected[16] = {
        0xE2, 0xF5, 0x65, 0x84, 0x41, 0x72, 0x67, 0x54, 0xD6, 0x3C, 0x90, 0xB8, 0x8D, 0xE2, 0xC7, 0x95
    };

    std::uint8_t aWorker[sizeof(aOriginal)] = {};
    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_16_A_PepperJumpNoiseXORCipher")) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_A_PepperJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_A_PepperJumpNoiseXORCipher failed after seal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aExpected, sizeof(aExpected)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aEncrypted, sizeof(aEncrypted)).c_str());
        return;
    }

    if (!CipherGauntlet::UnsealDataExpectingSuccess(aEncrypted,
                                                      aWorker,
                                                      aUnencrypted,
                                                      sizeof(aEncrypted),
                                                      &aCrypt,
                                                      "test_fixed_16_A_PepperJumpNoiseXORCipher")) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_A_PepperJumpNoiseXORCipher failed while unsealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aOriginal, aUnencrypted, sizeof(aOriginal))) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_A_PepperJumpNoiseXORCipher failed after unseal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aOriginal, sizeof(aOriginal)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aUnencrypted, sizeof(aUnencrypted)).c_str());
        return;
    }

}

- (void)test_fixed_16_B_PepperJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 11111111  11111111
    // bit1 11111111  11111111
    // bit2 11111111  11111111
    // bit3 11111111  11111111
    // bit4 11111111  11111111
    // bit5 11111111  11111111
    // bit6 11111111  11111111
    // bit7 11111111  11111111
    //
    // After Cipher:
    // bit0 00100110  01111111
    // bit1 00001110  00100010
    // bit2 10111000  11101010
    // bit3 00000010  11000101
    // bit4 00101111  00010001
    // bit5 10011110  10001001
    // bit6 10101000  10111111
    // bit7 01100110  01110011
    //
    // Avalanche:
    // bit0 XX.XX..X  X.......
    // bit1 XXXX...X  XX.XXX.X
    // bit2 .X...XXX  ...X.X.X
    // bit3 XXXXXX.X  ..XXX.X.
    // bit4 XX.X....  XXX.XXX.
    // bit5 .XX....X  .XXX.XX.
    // bit6 .X.X.XXX  .X......
    // bit7 X..XX..X  X...XX..
    // Avalanche: 50.78%

    const std::uint8_t aOriginal[16] = {
        0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF
    };

    const std::uint8_t aMaskBuffer[16] = {
        0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF
    };

    const std::uint8_t aNoiseBuffer[16] = {
        0x26, 0x01, 0xAB, 0x24, 0x6E, 0xCD, 0xDD, 0x08, 0x36, 0xB1, 0xE3, 0x8B, 0xA6, 0x92, 0xE3, 0x9F
    };

    const std::uint8_t aMaskJumpBuffer[16] = {
        0xC4, 0x11, 0x6B, 0xA8, 0x6F, 0x20, 0x8B, 0xDC, 0x4C, 0xDC, 0x4C, 0xF2, 0x80, 0x4A, 0xEC, 0xB0
    };

    PepperJumpNoiseXORCipher aCrypt(aMaskBuffer,
        aNoiseBuffer,
        aMaskJumpBuffer);

    const std::uint8_t aExpected[16] = {
        0x26, 0x01, 0xAB, 0x24, 0x6E, 0xCD, 0xDD, 0x08, 0x36, 0xB1, 0xE3, 0x8B, 0xA6, 0x92, 0xE3, 0x9F
    };

    std::uint8_t aWorker[sizeof(aOriginal)] = {};
    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_16_B_PepperJumpNoiseXORCipher")) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_B_PepperJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_B_PepperJumpNoiseXORCipher failed after seal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aExpected, sizeof(aExpected)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aEncrypted, sizeof(aEncrypted)).c_str());
        return;
    }

    if (!CipherGauntlet::UnsealDataExpectingSuccess(aEncrypted,
                                                      aWorker,
                                                      aUnencrypted,
                                                      sizeof(aEncrypted),
                                                      &aCrypt,
                                                      "test_fixed_16_B_PepperJumpNoiseXORCipher")) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_B_PepperJumpNoiseXORCipher failed while unsealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aOriginal, aUnencrypted, sizeof(aOriginal))) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_16_B_PepperJumpNoiseXORCipher failed after unseal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aOriginal, sizeof(aOriginal)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aUnencrypted, sizeof(aUnencrypted)).c_str());
        return;
    }

}

- (void)test_fixed_16_C_PepperJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 10101010  10101010
    // bit1 10101010  10101010
    // bit2 10101010  10101010
    // bit3 10101010  10101010
    // bit4 01010101  01010101
    // bit5 01010101  01010101
    // bit6 01010101  01010101
    // bit7 01010101  01010101
    //
    // After Cipher:
    // bit0 10101010  01100000
    // bit1 11010110  01011111
    // bit2 10000111  10010011
    // bit3 01011001  10100010
    // bit4 10101100  00110001
    // bit5 11000001  00110110
    // bit6 01000100  11011101
    // bit7 11010000  10011110
    //
    // Avalanche:
    // bit0 ........  XX..X.X.
    // bit1 .XXXXX..  XXXX.X.X
    // bit2 ..X.XX.X  ..XXX..X
    // bit3 XXXX..XX  ....X...
    // bit4 XXXXX..X  .XX..X..
    // bit5 X..X.X..  .XX...XX
    // bit6 ...X...X  X...X...
    // bit7 X....X.X  XX..X.XX
    // Avalanche: 45.31%

    const std::uint8_t aOriginal[16] = {
        0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F, 0xF0, 0x0F
