    const std::uint8_t aExpected[16] = {
        0xED, 0x57, 0x88, 0x51, 0x98, 0x6A, 0xE0, 0x34, 0x33, 0xC2, 0x9C, 0x6F, 0x43, 0x47, 0x75, 0x6A
