- (void)test_fixed_16_E_PepperJumpNoiseXORCipher {

    // Before Cipher:
    // bit0 10101010  10101010
    // bit1 10101010  10101010
    // bit2 01010101  01010101
    // bit3 01010101  01010101
    // bit4 01010101  01010101
    // bit5 01010101  01010101
    // bit6 10101010  10101010
    // bit7 10101010  10101010
    //
    // After Cipher:
    // bit0 11101101  01001101
    // bit1 01111101  10000101
    // bit2 11001001  10011100
    // bit3 00100011  11110111
    // bit4 11001110  01101101
    // bit5 11101010  10010111
    // bit6 11001000  10111010
    // bit7 00100101  10101110
    //
    // Avalanche:
    // bit0 .X...XXX  XXX..XXX
    // bit1 XX.X.XXX  ..X.XXXX
    // bit2 X..XXX..  XX..X..X
    // bit3 .XXX.XX.  X.X...X.
    // bit4 X..XX.XX  ..XXX...
    // bit5 X.XXXXXX  XX....X.
    // bit6 .XX...X.  ...X....
    // bit7 X...XXXX  .....X..
    // Avalanche: 50.78%

    const std::uint8_t aOriginal[16] = {
        0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C
    };

    const std::uint8_t aMaskBuffer[16] = {
        0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C, 0xC3, 0x3C
    };

    const std::uint8_t aNoiseBuffer[16] = {
        0xAE, 0xEE, 0xD5, 0x40, 0xEE, 0xC9, 0x1C, 0xF1, 0x77, 0x98, 0x1B, 0x36, 0xAB, 0xFD, 0x17, 0xDC
    };

    const std::uint8_t aMaskJumpBuffer[16] = {
        0xAA, 0xEC, 0x6F, 0x73, 0x49, 0x9C, 0xAA, 0x90, 0xA1, 0x05, 0x38, 0x95, 0x73, 0x02, 0x35, 0xCF
    };

    PepperJumpNoiseXORCipher aCrypt(aMaskBuffer,
