    // bit5 01010101  01010101  01010101  01010101
    // bit6 01010101  01010101  01010101  01010101
    // bit7 01010101  01010101  01010101  01010101
    //
    // After Cipher:
    // bit0 01010111  10100010  10111111  00000100
    // bit1 11010001  01100011  01001111  10100111
    // bit2 11111100  01010101  11010110  00010111
