    // bit4 00011110  11010000  10001101  11100101
    // bit5 00100000  00001001  11011011  01001010
    // bit6 00000000  10011111  10110000  11101110
    // bit7 11000101  11001100  00111111  10101100
    //
    // Avalanche:
    // bit0 XXXXXX.X  ....X...  ...X.X.X  X.X.XXX.
    // bit1 .XXXX.XX  XX..X..X  XXX..X.X  ....XX.X
    // bit2 .X.X.XX.  XXXXXXXX  .XXXXX..  X.XXXX.X
