    };

    const std::uint8_t aNoiseBuffer[32] = {
        0x71, 0xF1, 0x24, 0xF8, 0x28, 0xB9, 0x98, 0xC1, 0x9B, 0x69, 0xC0, 0x3A, 0x07, 0x23, 0xD2, 0x76,
        0xAE, 0x74, 0x93, 0xB7, 0xCD, 0xF9, 0xE5, 0xCD, 0x4B, 0x0E, 0x4B, 0x30, 0x07, 0xEB, 0x66, 0x68
    };

    const std::uint8_t aMaskJumpBuffer[32] = {
        0x3F, 0x6C, 0x1D, 0xAD, 0x4E, 0x53, 0x07, 0x9E, 0x77, 0x18, 0xC2, 0xC2, 0xF4, 0x63, 0x22, 0xF9,
        0x6F, 0xFD, 0x27, 0x4D, 0x86, 0x64, 0x58, 0x4A, 0x85, 0xB5, 0x7F, 0x70, 0xCF, 0x89, 0x2E, 0xBB
    };

    const std::uint8_t aNoiseJumpBuffer[32] = {
        0x09, 0x87, 0x1D, 0x2C, 0xA1, 0x94, 0x51, 0x8C, 0x14, 0x75, 0xDA, 0xC1, 0x4E, 0x7D, 0x4D, 0x2E,
        0x73, 0x6C, 0xFC, 0xF6, 0xF9, 0x42, 0x5F, 0x05, 0x33, 0xEB, 0xEE, 0x1B, 0x58, 0x91, 0x29, 0xC3
    };

    PepperJumpNoiseXORCipher aCrypt(aMaskBuffer,
        aNoiseBuffer,
        aMaskJumpBuffer);

    const std::uint8_t aExpected[32] = {
        0x71, 0xF1, 0x24, 0xF8, 0x28, 0xB9, 0x98, 0xC1, 0x9B, 0x69, 0xC0, 0x3A, 0x07, 0x23, 0xD2, 0x76,
