    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_32_C_PepperJumpNoiseXORCipher")) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_32_C_PepperJumpNoiseXORCipher failed while sealing.");
