    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_112_E_PepperJumpNoiseXORCipher failed after seal.");
