        0x58, 0x03, 0xDD, 0xC3, 0x47, 0xB3, 0xA2, 0x56, 0x98, 0xE8, 0x0A, 0xF4, 0x13, 0x53, 0x05, 0xFE,
        0x04, 0x51, 0x2C, 0x0E, 0xFC, 0x1F, 0x2C, 0x97, 0xC6, 0x09, 0xDD, 0x32, 0x85, 0x78, 0x8A, 0x87
    };

    std::uint8_t aWorker[sizeof(aOriginal)] = {};
    std::uint8_t aEncrypted[sizeof(aOriginal)] = {};
    std::uint8_t aUnencrypted[sizeof(aOriginal)] = {};

    if (!CipherGauntlet::SealDataExpectingSuccess(aOriginal,
                                                    aWorker,
                                                    aEncrypted,
                                                    sizeof(aOriginal),
                                                    &aCrypt,
                                                    "test_fixed_128_F_PepperJumpNoiseXORCipher")) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_128_F_PepperJumpNoiseXORCipher failed while sealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aExpected, aEncrypted, sizeof(aExpected))) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_128_F_PepperJumpNoiseXORCipher failed after seal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aExpected, sizeof(aExpected)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aEncrypted, sizeof(aEncrypted)).c_str());
        return;
    }

    if (!CipherGauntlet::UnsealDataExpectingSuccess(aEncrypted,
                                                      aWorker,
                                                      aUnencrypted,
                                                      sizeof(aEncrypted),
                                                      &aCrypt,
                                                      "test_fixed_128_F_PepperJumpNoiseXORCipher")) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_128_F_PepperJumpNoiseXORCipher failed while unsealing.");
        return;
    }

    if (!CipherGauntlet::Matches(aOriginal, aUnencrypted, sizeof(aOriginal))) {
        XCTFail("[PepperJumpNoiseXORCipher] test_fixed_128_F_PepperJumpNoiseXORCipher failed after unseal.");
        printf("Expected: %s\n", PrintExamplesHelper::HexArray(aOriginal, sizeof(aOriginal)).c_str());
        printf("Actual: %s\n", PrintExamplesHelper::HexArray(aUnencrypted, sizeof(aUnencrypted)).c_str());
        return;
    }

}

